                    "sql": "create or replace table snitch_db.maplemonk.prediction_sarima_xgboost as with predicted_sales as ( select to_date(date) as date, round((offline_sarima*store_carpet_area),0) as offline_sarima, round((offline_xgboost*store_carpet_area),0) as offline_xgboost, replace(shopify_sarima,\',\',\'\') as shopify_sarima, shopify_xgboost, marketplace_sarima, marketplace_xgboost from snitch_db.maplemonk.sarima_xgboost_sheet1 ), offline_actual_sales as ( select order_date as date, sum(selling_price) as offline_real from snitch_db.maplemonk.store_fact_items_offline where lower(marketplace_mapped) not like \'%wh%\' and order_date >= \'2024-10-24\' group by 1 ), shopify_actual_sales as ( select order_timestamp::date as date, sum(gross_sales) as shopify_real from snitch_db.maplemonk.fact_items_snitch where lower(ifnull(discount_code,\'n\')) not like \'%eco%\' and lower(ifnull(discount_code,\'n\')) not like \'%influ%\' and order_name not in (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') and tags not in (\'FLITS_LOGICERP\') and order_timestamp::date >= \'2024-10-24\' group by 1 ), marketplace_sales as ( select order_timestamp::date as date, sum(selling_price) as marketplace_real from snitch_db.maplemonk.unicommerce_fact_items_snitch where marketplace_mapped in (\'Myntra\',\'MYNTRA\',\'AMAZON\',\'FLIPKART\',\'AJIO\') and lower(marketplace_mapped) not like \'%wh%\' and order_date >= \'2024-10-24\' group by 1 ) select a.*, b.offline_real, c.shopify_real, d.marketplace_real from predicted_sales a left join offline_actual_sales b on a.date = b.date left join shopify_actual_sales c on a.date = c.date left join marketplace_sales d on a.date = d.date ; create or replace table snitch_db.maplemonk.shopify_prediction_sales_final as ( with target as ( select date, round(replace(shopify_sarima,\',\',\'\'),0) as Predicted_Gross_Sales, round(replace(shopify_sarima,\',\',\'\'),0)*1.15 as Target_Gross_Sales, round(replace(shopify_sarima,\',\',\'\')*0.5,0) as Predicted_New_Customer_Gross_Sales, round(replace(shopify_sarima,\',\',\'\')*0.5*1.15,0) as Target_New_Customer_Gross_Sales, round(replace(shopify_sarima,\',\',\'\')*0.5,0) as Predicted_Repeat_Customer_Gross_Sales, round(replace(shopify_sarima,\',\',\'\')*0.5*1.15,0) as Target_Repeat_Customer_Gross_Sales, 50 as Target_New_Customer_Gross_Sales_Percentage, 50 as Predicted_New_Customer_Gross_Sales_Percentage, 2000 as Predicted_AOV, 2000 as Target_AOV, 1900 as Predicted_New_Customer_AOV, 1900 as Target_New_Customer_AOV, 2100 as Predicted_Repeat_Customer_AOV, 2100 as Target_Repeat_Customer_AOV, round((replace(shopify_sarima,\',\',\'\')*0.5)/1900,0) as Predicted_New_Customer_Order, round((replace(shopify_sarima,\',\',\'\')*0.5*1.15)/1900,0) as Target_New_Customer_Order, round((replace(shopify_sarima,\',\',\'\')*0.5)/2100,0) as Predicted_Repeat_Customer_Order, round((replace(shopify_sarima,\',\',\'\')*0.5*1.15)/2100,0) as Target_Repeat_Customer_Order, round((((replace(shopify_sarima,\',\',\'\')*0.5)/1900) + ((replace(shopify_sarima,\',\',\'\')*0.5)/2100))/0.011,0) as Predicted_Sessions, round((((replace(shopify_sarima,\',\',\'\')*0.5*1.15)/1900) + ((replace(shopify_sarima,\',\',\'\')*0.5*1.15)/2100))/0.011,0) as Target_Sessions, round(replace(shopify_sarima,\',\',\'\')/5,0) as Predicted_Marketing_Spend, round(replace(shopify_sarima,\',\',\'\')*1.15/5,0) as Target_Marketing_Spend, round((replace(shopify_sarima,\',\',\'\')/5)/(replace(shopify_sarima,\',\',\'\')*0.5/1900),0) as Predicted_CAC, round((replace(shopify_sarima,\',\',\'\')*1.15/5)/(replace(shopify_sarima,\',\',\'\')*0.5*1.15/1900),0) as Target_CAC, round((replace(shopify_sarima,\',\',\'\')/5)/(replace(shopify_sarima,\',\',\'\')/2000),0) as Predicted_Overall_CAC, round((replace(shopify_sarima,\',\',\'\')*1.15/5)/(replace(shopify_sarima,\',\',\'\')*1.15/2000),0) as Target_Overall_CAC from snitch_db.maplemonk.prediction_sarima_xgboost order by date asc ), actual as ( select date, round(SUM(ifnull(gross_sales,0)),0) as Actual_Gross_Sales, round(SUM(ifnull(New_Customer_revenue,0)),0) as Actual_New_Customer_Gross_Sales, round(SUM(ifnull(Repeat_Customer_revenue,0)),0) as Actual_Repeat_Customer_Gross_Sales, round(div0(sum(ifnull(new_customer_revenue,0)),sum(ifnull(gross_sales,0)))*100,2) as Actual_New_Customer_Gross_Sales_Percentage, round(div0(sum(ifnull(gross_sales,0)),sum(ifnull(total_orders,0))),0) as Actual_AOV, round(div0(sum(ifnull(new_customer_revenue,0)),sum(ifnull(new_customer_orders,0))),0) as Actual_New_Customer_AOV, round(div0(sum(ifnull(repeat_customer_revenue,0)),sum(ifnull(repeat_customer_orders,0))),0) as Actual_Repeat_Customer_AOV, round(SUM(ifnull(New_Customer_Orders,0)),0) as Actual_New_Customer_Order, round(SUM(ifnull(Repeat_Customer_Orders,0)),0) as Actual_Repeat_Customer_Order, round(sum(ifnull(web_sessions,0))+sum(ifnull(appbrew_sessions,0))+sum(ifnull(app_ios_sessions,0))+sum(ifnull(app_android_sessions,0)),0) as Actual_Sessions, round(sum(ifnull(marketing_spend,0)),0) as Actual_Marketing_Spend, round(div0(sum(marketing_spend),sum(total_new_customers)),0) as Actual_CAC, round(div0(sum(marketing_spend),sum(total_orders)),0) as Actual_Overall_CAC from snitch_db.maplemonk.sales_cost_source_snitch group by date order by date asc ) SELECT a.date, \'Gross Sales\' AS Metric, Actual_Gross_Sales AS Actual, Predicted_Gross_Sales AS Predicted, Target_Gross_Sales AS Target, FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'New Customer Gross Sales\' AS Metric, Actual_New_Customer_Gross_Sales AS Actual, Predicted_New_Customer_Gross_Sales AS Predicted, Target_New_Customer_Gross_Sales AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'Repeat Customer Gross Sales\' AS Metric, Actual_Repeat_Customer_Gross_Sales AS Actual, Predicted_Repeat_Customer_Gross_Sales AS Predicted, Target_Repeat_Customer_Gross_Sales AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'New Customer Gross Sales Percentage\' AS Metric, Actual_New_Customer_Gross_Sales_Percentage AS Actual, Predicted_New_Customer_Gross_Sales_Percentage AS Predicted, Target_New_Customer_Gross_Sales_Percentage AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'AOV\' AS Metric, Actual_AOV AS Actual, Predicted_AOV AS Predicted, Target_AOV AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'New Customer AOV\' AS Metric, Actual_New_Customer_AOV AS Actual, Predicted_New_Customer_AOV AS Predicted, Target_New_Customer_AOV AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'Repeat Customer AOV\' AS Metric, Actual_Repeat_Customer_AOV AS Actual, Predicted_Repeat_Customer_AOV AS Predicted, Target_Repeat_Customer_AOV AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'New Customer Order\' AS Metric, Actual_New_Customer_Order AS Actual, Predicted_New_Customer_Order AS Predicted, Target_New_Customer_Order AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'Repeat Customer Order\' AS Metric, Actual_Repeat_Customer_Order AS Actual, Predicted_Repeat_Customer_Order AS Predicted, Target_Repeat_Customer_Order AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'Sessions\' AS Metric, Actual_Sessions AS Actual, Predicted_Sessions AS Predicted, Target_Sessions AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'Marketing Spend\' AS Metric, Actual_Marketing_Spend AS Actual, Predicted_Marketing_Spend AS Predicted, Target_Marketing_Spend AS Target FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'CAC\' AS Metric, Actual_CAC AS Actual, Predicted_CAC AS Predicted, Target_CAC AS Target, FROM actual a JOIN target t ON a.date = t.date UNION ALL SELECT a.date, \'Overall CAC\' AS Metric, Actual_Overall_CAC AS Actual, Predicted_Overall_CAC AS Predicted, Target_Overall_CAC AS Target FROM actual a JOIN target t ON a.date = t.date ); create or replace table snitch_db.maplemonk.actual_predicted_sales_inventory as ( with predicted as ( select date, round(replace(shopify_sarima,\',\',\'\'),0) as Predicted_Gross_Sales, round(replace(shopify_sarima,\',\',\'\')*1.15,0) as Target_Gross_Sales, from snitch_db.maplemonk.prediction_sarima_xgboost order by date asc ), actual as ( select date, round(SUM(ifnull(gross_sales,0)),0) as Actual_Gross_Sales, from snitch_db.maplemonk.sales_cost_source_snitch group by 1 order by date asc ), inventory as ( select date, sum(total_inventory) as total_inventory from snitch_db.maplemonk.cut_size_analysis where left(sku_group,2) != \'MP\' and live_date_final <= date group by 1 ) select a.*,b.Actual_Gross_Sales,c.total_inventory from predicted a left join actual b on a.date = b.date left join inventory c on a.date = c.date );",
                    "transaction": true
